#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
void handler(int sig) {
  printf("Caught signal %d\n", sig);
  exit(0);
}
int main(int argc, char **argv) {
  if (argc != 2) {
    fprintf(stderr, "usage: %s <seconds>\n", argv[0]);
    exit(1);
  }
  if (signal(SIGINT, handler) == SIG_ERR) /* Install SIGINT handler */
    perror("signal error");
  (void)sleep(atoi(argv[1]));
  return 0;
}
